        // check balances after minting
        uint256 defaultFee = ((_mintrequest.pricePerToken * _mintrequest.quantity) * 50) / MAX_BPS;
        uint256 _platformFees = ((_mintrequest.pricePerToken * _mintrequest.quantity) * platformFeeBps) / MAX_BPS;
