        assertEq(tokenContract.primarySaleRecipient(), saleRecipient);

        assertTrue(tokenContract.hasRole(bytes32(0x00), deployer));
        assertTrue(tokenContract.hasRole(keccak256("TRANSFER_ROLE"), deployer));
