            assertEq(modules[i].chainId, chainIds[i]);
        }

        vm.prank(factory_);
        _registry.add(deployer_, address(0x43), 111, "");

        modules = _registry.getAll(deployer_);
        assertEq(modules.length, total + 1);
        assertEq(_registry.count(deployer_), total + 1);
    }

