function test_initialize() public whenNotImplementation whenProxyNotInitialized {
        MyVoteERC20(proxy).initialize(
            NAME,
            CONTRACT_URI,
            forwarders(),
            token,
            initialVotingDelay,
            initialVotingPeriod,
            initialProposalThreshold,
            initialVoteQuorumFraction
        );

        // check state
